-- Repository connectors: GitHub, Azure DevOps Repos, GitLab, Bitbucket Cloud, Bitbucket Data Center and Gitea / Forgejo.
-- The catalog rows below match src/infrastructure/database/seeds/connector-catalog.seed.ts.
INSERT INTO "connector_types" ("code", "name", "description", "sort_order")
VALUES ('repository', 'Repository', 'Source code repositories on GitHub, Azure DevOps, GitLab, Bitbucket and Gitea', 4)
ON CONFLICT ("code") DO UPDATE SET "name" = EXCLUDED."name", "description" = EXCLUDED."description", "sort_order" = EXCLUDED."sort_order", "updated_at" = now();
--> statement-breakpoint
-- GitHub moves from Data to Repository with a repository-scoped configuration, so its existing row is replaced.
INSERT INTO "connector_catalog" ("code", "name", "connector_type", "category", "description", "adapter_key", "config_schema", "is_enabled")
VALUES
    ('github', 'GitHub', 'repository', 'Hosted platforms', 'Read a GitHub.com or GitHub Enterprise Server repository: files, branches, commits and pull requests.', 'repository.github', '{"type":"object","properties":{"apiUrl":{"type":"string","title":"API URL","minLength":1,"description":"Leave empty for GitHub.com. For GitHub Enterprise Server enter https://<host>/api/v3.","format":"uri"},"owner":{"type":"string","title":"Owner","minLength":1,"description":"User or organization that owns the repository.","pattern":"^[A-Za-z0-9_.-]+$","maxLength":100},"repository":{"type":"string","title":"Repository","minLength":1,"pattern":"^[A-Za-z0-9_.-]+$","maxLength":100},"token":{"type":"string","title":"Access token","minLength":1,"x-secret":true,"description":"Fine-grained or classic personal access token with read access to contents, metadata and pull requests."}},"required":["owner","repository","token"],"additionalProperties":false,"x-icon":"devicon:GithubIcon"}'::jsonb, true),
    ('azure-devops-repos', 'Azure DevOps Repos', 'repository', 'Hosted platforms', 'Read an Azure Repos Git repository in Azure DevOps Services or Azure DevOps Server.', 'repository.azure-devops', '{"type":"object","properties":{"organizationUrl":{"type":"string","title":"Organization URL","minLength":1,"description":"https://dev.azure.com/<organization> for Azure DevOps Services, or https://<server>/<collection> for Azure DevOps Server.","format":"uri"},"project":{"type":"string","title":"Project","minLength":1},"repository":{"type":"string","title":"Repository","minLength":1},"token":{"type":"string","title":"Personal access token","minLength":1,"x-secret":true,"description":"Needs the Code (Read) scope."}},"required":["organizationUrl","project","repository","token"],"additionalProperties":false,"x-icon":"devicon:MicrosoftAzure"}'::jsonb, true),
    ('gitlab', 'GitLab', 'repository', 'Hosted platforms', 'Read a GitLab.com or self-managed GitLab project: files, branches, commits and merge requests.', 'repository.gitlab', '{"type":"object","properties":{"serverUrl":{"type":"string","title":"Server URL","minLength":1,"description":"Leave empty for GitLab.com, or enter your self-managed GitLab address.","format":"uri"},"projectPath":{"type":"string","title":"Project path","minLength":1,"description":"Full path of the project, such as group/subgroup/project.","pattern":"^[A-Za-z0-9_.-]+(/[A-Za-z0-9_.-]+)+$"},"token":{"type":"string","title":"Access token","minLength":1,"x-secret":true,"description":"Personal, group or project access token with the read_api scope."}},"required":["projectPath","token"],"additionalProperties":false,"x-icon":"devicon:Gitlab"}'::jsonb, true),
    ('bitbucket-cloud', 'Bitbucket Cloud', 'repository', 'Hosted platforms', 'Read a bitbucket.org repository: files, branches, commits and pull requests.', 'repository.bitbucket-cloud', '{"type":"object","properties":{"workspace":{"type":"string","title":"Workspace","minLength":1,"description":"Workspace ID shown in the repository URL.","pattern":"^[A-Za-z0-9_.-]+$","maxLength":100},"repository":{"type":"string","title":"Repository","minLength":1,"description":"Repository slug shown in the repository URL.","pattern":"^[A-Za-z0-9_.-]+$","maxLength":100},"authentication":{"type":"string","title":"Authentication","enum":["api-token","access-token"],"enumNames":["API token with Atlassian account email","Repository or workspace access token"]},"email":{"type":"string","title":"Atlassian account email","minLength":1,"format":"email","x-visibleWhen":{"authentication":"api-token"}},"token":{"type":"string","title":"Token","minLength":1,"x-secret":true,"description":"API token with repository read scopes, or a repository or workspace access token."}},"required":["workspace","repository","authentication","token"],"additionalProperties":false,"allOf":[{"if":{"properties":{"authentication":{"const":"api-token"}},"required":["authentication"]},"then":{"required":["email"]}}],"x-icon":"devicon:Bitbucket"}'::jsonb, true),
    ('bitbucket-data-center', 'Bitbucket Data Center', 'repository', 'Self-hosted servers', 'Read a repository on a Bitbucket Data Center or Bitbucket Server instance.', 'repository.bitbucket-data-center', '{"type":"object","properties":{"serverUrl":{"type":"string","title":"Server URL","minLength":1,"description":"Base address of your Bitbucket instance, such as https://bitbucket.example.com.","format":"uri"},"projectKey":{"type":"string","title":"Project key","minLength":1,"description":"Project key, or ~username for a personal repository.","pattern":"^~?[A-Za-z0-9_-]+$"},"repository":{"type":"string","title":"Repository","minLength":1,"description":"Repository slug shown in the repository URL.","pattern":"^[A-Za-z0-9_.-]+$","maxLength":100},"token":{"type":"string","title":"HTTP access token","minLength":1,"x-secret":true,"description":"Personal, project or repository HTTP access token with repository read permission."}},"required":["serverUrl","projectKey","repository","token"],"additionalProperties":false,"x-icon":"devicon:Bitbucket"}'::jsonb, true),
    ('gitea', 'Gitea / Forgejo', 'repository', 'Self-hosted servers', 'Read a repository on a Gitea or Forgejo server, including Codeberg.', 'repository.gitea', '{"type":"object","properties":{"serverUrl":{"type":"string","title":"Server URL","minLength":1,"description":"Base address of the server, such as https://gitea.example.com or https://codeberg.org.","format":"uri"},"owner":{"type":"string","title":"Owner","minLength":1,"description":"User or organization that owns the repository.","pattern":"^[A-Za-z0-9_.-]+$","maxLength":100},"repository":{"type":"string","title":"Repository","minLength":1,"pattern":"^[A-Za-z0-9_.-]+$","maxLength":100},"token":{"type":"string","title":"Access token","minLength":1,"x-secret":true,"description":"Access token with the read:repository scope."}},"required":["serverUrl","owner","repository","token"],"additionalProperties":false,"x-icon":"lucide:GitBranch"}'::jsonb, true)
