-- Connections made with the old GitHub entry follow it to the Repository type. Their saved settings used the old
-- user-endpoint form, so they are marked for reconfiguration.
UPDATE "connections" AS c
SET "connection_type" = 'repository', "status" = 'error', "updated_at" = now()
FROM "connector_catalog" AS k
WHERE c."catalog_id" = k."id" AND k."code" = 'github' AND c."connection_type" <> 'repository';
